function careerBody({
  opening,
  definition,
  workflow,
  responsibilities,
  example,
  skills,
  preparation,
  boundaries,
  links = [],
  faqs,
}) {
  return [
    paragraph(opening),
    heading('What the role means'),
    paragraph(definition),
    heading('A practical workflow'),
    list(workflow, true),
    paragraph('The sequence is a learning model, not a universal employer procedure. Team structures, systems, approval rights, service levels, market cut-offs, and escalation routes differ. A candidate should use the model to ask better questions and then follow the documented process of the organisation they join.'),
    heading('Responsibilities and useful evidence'),
    list(responsibilities),
    paragraph('Good work leaves a clear evidence trail. A reviewer should be able to see what entered the process, which checks were completed, what differed from expectation, who owned the next action, and how closure was confirmed. Speed matters only alongside accuracy, control completion, and appropriate escalation.'),
    heading('Fictional practice example'),
    paragraph(example),
    heading('Skills to build'),
    list(skills),
    heading('Preparation roadmap for graduates'),
    paragraph(preparation),
    list([
      'Read current job descriptions and group the repeated tasks, tools, products, and eligibility requirements.',
      'Map one end-to-end process and label its inputs, checks, outputs, owners, deadlines, and exception routes.',
      'Create a small exercise with invented data, then write a concise status or escalation note supported by evidence.',
      'Practise explaining what you know, what you would verify, and which decision requires an authorised reviewer.',
      'Review the target role again after practice and close the most important skill gap rather than collecting unrelated certificates.',
    ], true),
    heading('Role boundaries and career decisions'),
    paragraph(boundaries),
    paragraph('Role titles are not standard across employers. Compare the actual outputs, product coverage, shifts, systems, controls, location, and progression criteria in each vacancy. This guide does not promise eligibility, employment, a particular employer, or an outcome; it helps learners understand the work and prepare evidence of relevant thinking.'),
    ...links,
    heading('Common questions'),
    ...faqs.map(({ question, answer }) => faq(question, answer)),
  ];
}

function resourceBody({
  opening,
  scope,
  map,
  workflow,
  example,
  controls,
  study,
  links = [],
  faqs,
}) {
  return [
    paragraph(opening),
    heading('Scope of this resource'),
    paragraph(scope),
    heading('Concept map'),
    list(map),
    heading('How the workflow fits together'),
    list(workflow, true),
    paragraph('This sequence is intentionally generic. The authoritative record, cut-off, review level, market convention, and reporting obligation depend on the product and institution. Use current official material and the employer procedure before applying the framework to a live case.'),
    heading('Worked learning example'),
    paragraph(example),
    heading('Controls and questions to ask'),
    list(controls),
    paragraph('A control is useful when its purpose, owner, evidence, frequency, exception route, and completion standard are clear. Simply ticking a box does not establish that the underlying risk was addressed. Learners should be able to explain why a check exists and what they would do when the evidence is incomplete.'),
    heading('How to study and use this page'),
    paragraph(study),
    list([
      'Rewrite the concept map in your own words without adding facts you cannot support.',
      'Build a one-page process diagram showing records, teams, hand-offs, checks, and outputs.',
      'Create one fictional normal case and one exception case, keeping all names and values invented.',
      'Compare the exercise with current official guidance and a real job description.',
      'Record which details remain organisation-specific and would need confirmation in a live role.',
    ], true),
    ...links,
    heading('Common questions'),
    ...faqs.map(({ question, answer }) => faq(question, answer)),
  ];
}

function landingBody({ opening, fit, coverage, practice, planningMilestones, planningNote, checks, links, faqs }) {
  return [
    paragraph(opening),
    heading('Who this page is for'),
    paragraph(fit),
    heading('What the current learning path covers'),
    list(coverage),
    paragraph('These subjects are presented within Centaur Careers\' Financial Operations Masterclass. This page is a decision aid for that existing program, not a new standalone class, university qualification, professional charter, or regulatory licence.'),
    heading('What practical preparation should look like'),
    paragraph(practice),
    list([
      'Understand a workflow before memorising role titles or software names.',
      'Practise with fictional records so the reasoning can be reviewed safely.',
      'Explain controls, exceptions, evidence, ownership, and escalation in plain language.',
      'Compare practice tasks with current vacancies and close role-specific gaps.',
    ]),
    ...(planningMilestones?.length ? [
      heading('A six-week study-planning outline'),
      list(planningMilestones, true),
      paragraph(planningNote || 'This is an illustrative study plan, not a published cohort timetable. Confirm the actual session order and weekly effort with Centaur Careers.'),
    ] : []),
    heading('What to confirm before enrolling'),
    list(checks),
    paragraph('Ask for current information in writing when your decision depends on a fee, schedule, learning mode, assessment, certificate, eligibility condition, refund term, or career-support promise. Published details can change between cohorts, and no page should be treated as a substitute for the applicable written terms.'),
    heading('How to measure useful progress'),
    paragraph('Useful progress is more specific than completing videos or collecting notes. A learner should be able to explain a workflow from trigger to output, recognise the records and controls involved, investigate a small fictional exception, and communicate the next action without overstating authority. Compare that evidence with the tasks in current vacancies and ask for feedback on accuracy, clarity, and reasoning. If the work still feels unclear, identify the exact foundation or practice gap before buying another course.'),
    list([
      'Can you explain the process and why each control exists?',
      'Can you show a safe exercise built from invented rather than confidential data?',
      'Can you distinguish a fact, an assumption, an unresolved question, and an authorised decision?',
      'Can you connect your evidence to the requirements of a current target vacancy?',
    ]),
    ...links,
    heading('Common questions'),
    ...faqs.map(({ question, answer }) => faq(question, answer)),
  ];
}

